import math

fin = ["e01", "e05", "e12", "e13", "e21", "e27", "e39"]
c4_var = {"e01":"A","e05":"B","e12":"B","e13":"A","e21":"B","e27":"C","e39":"C"}

# Access logs days 1..5 for Finance employees: (normal_count, after_hours_count) per day
# Let us list exact logs from tool outputs:
raw_logs = {
  1: [("e12",False),("e12",False),("e12",True),("e13",True),("e39",False)],
  2: [("e01",False),("e01",True),("e05",False),("e13",False),("e21",False),("e27",False)],
  3: [("e01",False),("e01",False),("e12",False),("e21",False),("e27",False),("e27",False),("e39",False),("e39",False),("e39",False)],
  4: [("e01",False),("e05",False),("e12",False),("e12",False),("e12",False),("e13",False),("e27",False),("e27",False)],
  5: [("e01",False),("e01",True),("e01",False),("e12",False)]
}

interviews = {
  "e01": [False, False],
  "e05": [True, False],
  "e12": [False, False],
  "e13": [True, False],
  "e21": [False, False],
  "e27": [False],
  "e39": [False]
}

# Number of non-mole non-decoy employees holding >=1 doc on each day d:
# Day 1: 28 held docs -> minus mole minus decoy = 26
# Day 2: 28 held docs -> 26
# Day 3: 40 held docs -> 38
# Day 4: 40 held docs -> 38
# Day 5: 40 held docs -> 38
n_other = {1: 26, 2: 26, 3: 38, 4: 38, 5: 38}

def pois_pmf(k, lam):
    return (lam**k) * math.exp(-lam) / math.factorial(k)

scores = {}
for m in fin:
    # Canary c4 likelihood
    p = 0.95 if c4_var[m] == "B" else 0.025
    # Interviews
    for s in fin:
        for ev in interviews[s]:
            if s == m:
                p *= (0.24 if ev else 0.76)
            else:
                p *= (0.20 if ev else 0.80)
    # Access logs:
    # Mole: normal ~ Pois(0.7), after_hours ~ Pois(0.3)
    # Innocent non-decoy: normal ~ Pois(0.9), after_hours ~ Pois(0.1 + 1.0 / n_other[d])
    for d in range(1, 6):
        for s in fin:
            n_cnt = sum(1 for e, ah in raw_logs[d] if e == s and not ah)
            ah_cnt = sum(1 for e, ah in raw_logs[d] if e == s and ah)
            if s == m:
                p *= pois_pmf(n_cnt, 0.7) * pois_pmf(ah_cnt, 0.3)
            else:
                lam_ah = 0.1 + 1.0 / n_other[d]
                p *= pois_pmf(n_cnt, 0.9) * pois_pmf(ah_cnt, lam_ah)
    scores[m] = p

tot = sum(scores.values())
for m in sorted(fin, key=lambda x: -scores[x]):
    n_tot = sum(1 for d in range(1,6) for e,ah in raw_logs[d] if e==m and not ah)
    ah_tot = sum(1 for d in range(1,6) for e,ah in raw_logs[d] if e==m and ah)
    print(f"{m} (c4={c4_var[m]}): P = {scores[m]/tot:.4f} (normal={n_tot}, ah={ah_tot}, iv={interviews[m]})")
'

